-- Run in Supabase SQL Editor. Never put a service_role key in the browser.
create extension if not exists pgcrypto;
create table if not exists public.households(id uuid primary key default gen_random_uuid(),name text not null default 'Our Household',invite_code text not null unique default upper(substr(encode(gen_random_bytes(8),'hex'),1,8)),created_by uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now());
create table if not exists public.household_members(id uuid primary key default gen_random_uuid(),household_id uuid not null references public.households(id) on delete cascade,user_id uuid not null unique references auth.users(id) on delete cascade,display_name text,role text not null default 'member' check(role in('owner','member')),joined_at timestamptz not null default now());
create table if not exists public.transactions(id uuid primary key default gen_random_uuid(),household_id uuid not null references public.households(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,description text not null,amount numeric(12,2) not null check(amount>0),transaction_type text not null check(transaction_type in('Expense','Income','Investment','Debt Payment','Transfer','Refund')),main_category text not null,subcategory text not null,payment_method text not null default 'UPI',transaction_date date not null default current_date,notes text,created_at timestamptz not null default now());
create index if not exists tx_household_date_idx on public.transactions(household_id,transaction_date desc);
alter table public.households enable row level security;alter table public.household_members enable row level security;alter table public.transactions enable row level security;
create or replace function public.is_household_member(hid uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.household_members where household_id=hid and user_id=auth.uid()) $$;
create policy "members view household" on public.households for select using(public.is_household_member(id));
create policy "members view membership" on public.household_members for select using(public.is_household_member(household_id));
create policy "members view household transactions" on public.transactions for select using(public.is_household_member(household_id));
create policy "members insert own transactions" on public.transactions for insert with check(public.is_household_member(household_id) and user_id=auth.uid());
create policy "owners update own transactions" on public.transactions for update using(user_id=auth.uid() and public.is_household_member(household_id)) with check(user_id=auth.uid() and public.is_household_member(household_id));
create policy "owners delete own transactions" on public.transactions for delete using(user_id=auth.uid() and public.is_household_member(household_id));
create or replace function public.create_household(p_name text) returns public.households language plpgsql security definer set search_path=public as $$ declare h public.households; begin if auth.uid() is null then raise exception 'Sign in first'; end if; if exists(select 1 from public.household_members where user_id=auth.uid()) then raise exception 'This account already belongs to a household'; end if; insert into public.households(name,created_by) values(coalesce(nullif(trim(p_name),''),'Our Household'),auth.uid()) returning * into h; insert into public.household_members(household_id,user_id,role,display_name) values(h.id,auth.uid(),'owner',coalesce(auth.jwt()->'user_metadata'->>'name',split_part(auth.jwt()->>'email','@',1))); return h; end $$;
create or replace function public.join_household(p_code text) returns void language plpgsql security definer set search_path=public as $$ declare h public.households; begin if auth.uid() is null then raise exception 'Sign in first'; end if; if exists(select 1 from public.household_members where user_id=auth.uid()) then raise exception 'This account already belongs to a household'; end if; select * into h from public.households where invite_code=upper(trim(p_code)); if h.id is null then raise exception 'Invalid invite code'; end if; insert into public.household_members(household_id,user_id,role,display_name) values(h.id,auth.uid(),'member',coalesce(auth.jwt()->'user_metadata'->>'name',split_part(auth.jwt()->>'email','@',1))); end $$;
grant execute on function public.create_household(text) to authenticated;grant execute on function public.join_household(text) to authenticated;
